// State/UT -> District -> Assembly Constituency data from the Election Commission of India's
// Voters' Services Portal master lists, generated by scripts/build-geography-eci.js.
// Do not edit geography.json by hand; see docs/CONSTITUENCY_DATA.md.
import geography from "./geography.json" with { type: "json" };

export { geography };

const findState = (state) => geography.states.find((s) => s.name === state);

/** "31 – VIKASPURI"; the number and name exactly as ECI lists them. */
export const formatConstituency = (c) => (c ? `${c.no} – ${c.name}` : "");

/**
 * Name-based check used by the older registration request and by Form 8 corrections.
 * Returns an error message if the State/UT, district and constituency name do not form a
 * combination present in the dataset, otherwise null. Names must match exactly.
 */
export const validateGeography = ({ state, district, assemblyConstituency }) => {
    const stateEntry = findState(state);
    if (!stateEntry) return "Select a valid State/UT.";
    const districtEntry = stateEntry.districts.find((d) => d.name === district);
    if (!districtEntry) return "Select a valid district for the selected State/UT.";
    if (stateEntry.constituencies !== "available") {
        return "Constituency data is not available for the selected State/UT.";
    }
    if (!districtEntry.constituencies.includes(assemblyConstituency)) {
        return "Select a valid assembly constituency for the selected district.";
    }
    return null;
};

/**
 * Identifier-based check used by the Form 6 page. `constituencyId` is "<ECI state code>-<number>",
 * for example "U05-31". The constituency must belong to the selected State/UT and be one of the
 * options offered for the selected district. Returns { error } or the resolved, official values.
 */
export const resolveConstituency = ({ state, district, constituencyId }) => {
    const stateEntry = findState(state);
    if (!stateEntry) return { error: "Select a valid State/UT." };
    const districtEntry = stateEntry.districts.find((d) => d.name === district);
    if (!districtEntry) return { error: "Select a valid district for the selected State/UT." };
    const id = String(constituencyId ?? "").trim();
    if (!id) return { error: "Select the constituency." };
    if (!id.startsWith(`${stateEntry.code}-`)) return { error: "The selected constituency does not belong to the selected State/UT." };
    const ac = districtEntry.acs.find((a) => a.id === id);
    if (!ac) return { error: "The selected constituency does not belong to the selected district." };
    return {
        state: stateEntry.name,
        stateCode: stateEntry.code,
        district: districtEntry.name,
        districtCode: districtEntry.code,
        constituency: { ...ac, type: stateEntry.constituencyType, districtScope: districtEntry.acScope }
    };
};
